let accumulator=0,lastTime=0,lastRender=0,lastUI=0;function loop(t){let elapsed=lastTime?Math.min(1000,t-lastTime):0;lastTime=t;if(ready&&writer&&!paused&&!document.hidden){accumulator+=elapsed*speed;let steps=0;while(accumulator>=1000&&steps<4){step(state);accumulator-=1000;steps++;emit()}if(steps)updateUI()}if(t-lastRender>=(settings.quality==='low'?32:15)&&active==='network'){let dt=Math.min(100,t-lastRender);if(lastRender)frameTimes.push(dt);if(frameTimes.length>180)frameTimes.shift();render(t,dt);lastRender=t;}requestAnimationFrame(loop)}
